//! Prax models.
//!
//! Field types are deliberately limited to the scalar set Prax binds directly
//! (`String`, `i64`, `bool`, and `Option` of those). Instants are epoch-seconds
//! `i64`; identifiers are UUID v4 strings generated by [`new_id`], so ids are
//! stable and known to the caller before the insert. (Prax still appends a
//! `RETURNING` clause to every create, so the round-trip happens regardless —
//! what the client-generated id buys is a key the caller can use in the same
//! breath, not a saved query.)
//!
//! # The SQL schema is the contract
//!
//! `migrations/` is authoritative. Several constraints it declares cannot be
//! expressed on these models: Prax has no composite-unique attribute, so
//! `oauth_identities (provider, subject)` and `totp_replays (publisher_id,
//! time_step)` exist only in SQL — and the TOTP replay burn depends on the
//! latter being enforced there. Do not read these structs as the whole contract.

use prax_orm::{Model, client};

/// A person who can own applications and publish builds.
#[derive(Model, Debug, Clone)]
#[prax(table = "publishers")]
pub struct Publisher {
    #[prax(id)]
    pub id: String,
    #[prax(unique)]
    pub email: String,
    pub display_name: String,
    /// `None` for accounts created purely through GitHub/Google sign-in.
    pub password_hash: Option<String>,
    /// [`crate::auth::otp::OtpMethod`] serialized as `"totp"` or `"email"`.
    pub otp_method: String,
    /// The confirmed secret. Authoritative for verification.
    pub totp_secret: Option<String>,
    /// A secret enrolled but not yet proven. Promoted to `totp_secret` by
    /// `confirmTotp`; until then the confirmed secret keeps working, so opening
    /// a re-enrollment cannot downgrade an account to password-only sign-in.
    pub totp_pending_secret: Option<String>,
    pub totp_confirmed: bool,
    pub is_admin: bool,
    pub created_at: i64,
}

/// A remote account (GitHub, Google) linked to a [`Publisher`].
///
/// Uniqueness is on `(provider, subject)` in SQL — a composite constraint Prax
/// cannot express here. See `migrations/0001_init.sql`.
#[derive(Model, Debug, Clone)]
#[prax(table = "oauth_identities")]
pub struct OauthIdentity {
    #[prax(id)]
    pub id: String,
    pub publisher_id: String,
    /// `"github"` or `"google"`.
    pub provider: String,
    /// The provider's stable user identifier. Never the email, which can change.
    pub subject: String,
    pub email: Option<String>,
    pub created_at: i64,
}

/// A published Flatpak application.
#[derive(Model, Debug, Clone)]
#[prax(table = "applications")]
pub struct Application {
    #[prax(id)]
    pub id: String,
    #[prax(unique)]
    pub app_id: String,
    pub name: String,
    pub summary: String,
    pub description: String,
    pub homepage: Option<String>,
    pub license: Option<String>,
    pub publisher_id: String,
    pub created_at: i64,
}

/// One imported bundle: a single OSTree ref at a single commit.
#[derive(Model, Debug, Clone)]
#[prax(table = "builds")]
pub struct Build {
    #[prax(id)]
    pub id: String,
    pub application_id: String,
    /// One live build per ref; see `builds_ref_key` in the initial migration.
    #[prax(unique)]
    pub flatpak_ref: String,
    pub arch: String,
    pub branch: String,
    pub version: String,
    pub commit_id: String,
    pub bundle_key: String,
    pub size_bytes: i64,
    pub sha256: String,
    pub published_by: String,
    pub published_at: i64,
}

/// An outstanding emailed one-time code.
#[derive(Model, Debug, Clone)]
#[prax(table = "otp_challenges")]
pub struct OtpChallenge {
    #[prax(id)]
    pub id: String,
    pub publisher_id: String,
    pub purpose: String,
    pub code_hash: String,
    pub expires_at: i64,
    pub consumed: bool,
    pub created_at: i64,
}

/// One gallery item belonging to an application.
///
/// Uniqueness is on `(application_id, object_key)` in SQL — a composite
/// constraint Prax cannot express here. See `migrations/0003_screenshots.sql`.
#[derive(Model, Debug, Clone)]
#[prax(table = "screenshots")]
pub struct Screenshot {
    #[prax(id)]
    pub id: String,
    pub application_id: String,
    /// Object key in the bundle bucket.
    pub object_key: String,
    /// [`crate::screenshots::MediaFormat`] as `"png"`, `"jpg"`, `"webp"`, or `"webm"`.
    pub format: String,
    /// Order in the gallery, 0-based.
    pub position: i64,
    pub size_bytes: i64,
    pub sha256: String,
    pub created_at: i64,
}

/// A TOTP time-step already spent by a publisher, to block replay.
///
/// Uniqueness is on `(publisher_id, time_step)` in SQL — a composite constraint
/// Prax cannot express here, and the one the burn in `OtpService::verify_totp`
/// relies on to make a concurrent replay fail.
#[derive(Model, Debug, Clone)]
#[prax(table = "totp_replays")]
pub struct TotpReplay {
    #[prax(id)]
    pub id: String,
    pub publisher_id: String,
    pub time_step: i64,
    pub created_at: i64,
}

// Attaches `.publisher()`, `.application()`, `.build()`, … accessors to
// `PraxClient<E>` through the generated `PraxClientExt` trait.
client!(
    Publisher,
    OauthIdentity,
    Application,
    Build,
    Screenshot,
    OtpChallenge,
    TotpReplay,
);

/// Generate a fresh row identifier.
pub fn new_id() -> String {
    uuid::Uuid::new_v4().to_string()
}

/// Current time as epoch seconds, the unit every `*_at` column uses.
pub fn now_secs() -> i64 {
    chrono::Utc::now().timestamp()
}
